sql.where:
r.user_id = #{userId}
AND r.session_id = #{req.sessionId}
AND r.state = #{req.state}
AND r.created_at >= to_timestamp(#{req.from} / 1000.0)
AND r.created_at <= to_timestamp(#{req.to} / 1000.0)

    AND r.prompt LIKE '%' || #{req.keyword} || '%'

mapper.select:
SELECT r.* FROM wb_run r

ORDER BY r.created_at DESC
LIMIT #{size} OFFSET #{offset}
